import math
def control(o):
    h=o['hitch_deg']
    cam=o.get('views',{}).get('camera')
    desired=0.0
    if cam:
        a=math.radians(o['rig']['trailer_heading_deg'])
        pts=[]
        for b,d in cam.get('walls',[]):
            b=math.radians(b)
            x=d*math.cos(b); y=d*math.sin(b)
            u=-x*math.cos(a)-y*math.sin(a)
            z=-x*math.sin(a)+y*math.cos(a)
            pts.append((u,z))
        groups=[]; g=[]
        for p in pts:
            if g and (p[0]<g[-1][0]-2 or math.hypot(p[0]-g[-1][0],p[1]-g[-1][1])>4):
                groups.append(g); g=[]
            g.append(p)
        if g: groups.append(g)
        vals=[]
        L=5.5
        for g in groups:
            g=sorted(g)
            if len(g)<3 or g[0][0]>3 or g[-1][0]<L-1: continue
            val=min(g,key=lambda p:abs(p[0]-L))[1]
            for p,q in zip(g,g[1:]):
                if p[0]<=L<=q[0] and q[0]>p[0]:
                    val=p[1]+(q[1]-p[1])*(L-p[0])/(q[0]-p[0]); break
            vals.append(val)
        if len(vals)>=2:
            center=(min(vals)+max(vals))/2
            desired=math.degrees(math.atan(7.3*center/(L*L)))
    desired=max(-28,min(28,desired))
    steer=max(-34,min(34,0.7*h+1.7*(h-desired)))
    return (steer,-0.65,-23)

