import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    err=0.0
    if cam:
        sides=[[],[]]
        axis=math.radians(180-h)
        for b,d in cam.get('walls',[]):
            a=math.radians(b)-axis
            x=d*math.cos(a); y=d*math.sin(a)
            if x>2 and abs(y)>1:
                sides[0 if y>0 else 1].append((x,y))
        aims=[]
        for s in sides:
            if s:
                near=sorted(s,key=lambda p:abs(p[0]-9))[:3]
                aims.append((sum(p[0] for p in near)/len(near),sum(p[1] for p in near)/len(near)))
        if len(aims)==2:
            x=(aims[0][0]+aims[1][0])/2
            y=(aims[0][1]+aims[1][1])/2
            err=math.degrees(math.atan2(y,x))
    steer=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))+1.7*err
    return (max(-42,min(42,steer)),-1.0,-41)

